select distinct m.menu_id, m.parent_id, m.menu_name, m.path, m.component, m.visible, m.status, coalesce(m.perms,'') as perms, m.is_frame, m.is_cache, m.menu_type, m.icon, m.order_num, m.create_time, m.menu_position
from sys_menu m inner join sys_tenant_role_menu tm on m.menu_id = tm.menu_id where m.menu_type in ('M', 'C') and m.status = '0' and tm.role_id = #{tenantRoleId}
